actions.script:
def tenant = access.tenant
def org = tenant.organizationPartyId
boolean disabled = ec.artifactExecution.disableAuthz()
try {
    // One target tenant group, plus authoritative org relationships. Never use the viewer's
    // other groups or another user's editable ACTIVE_ORGANIZATION as a billing seat anchor.
    def users = new HashSet()
    if (tenant.subdomain) {
        users.addAll(ec.entity.find('moqui.security.UserGroupMember')
            .condition('userGroupId', 'TENANT_' + tenant.subdomain.toUpperCase(java.util.Locale.ROOT))
            .conditionDate('fromDate','thruDate',ec.user.nowTimestamp).list()*.userId)
    }
    def partyIds = ec.entity.find('mantle.party.PartyRelationship').condition('toPartyId',org)
        .condition('toRoleTypeId','OrgInternal').conditionDate('fromDate','thruDate',ec.user.nowTimestamp)
        .list()*.fromPartyId
    if (partyIds) users.addAll(ec.entity.find('moqui.security.UserAccount').condition('partyId','in',partyIds).list()*.userId)
    if (tenant.adminUserId) users.add(tenant.adminUserId)
    def activeUsers = users ? ec.entity.find('moqui.security.UserAccount').condition('userId','in',new ArrayList(users))
        .list().count { it.disabled != 'Y' } : 0
    def month = java.time.YearMonth.from(ec.user.nowTimestamp.toLocalDateTime())
    def start = java.sql.Timestamp.valueOf(month.atDay(1).atStartOfDay())
    def end = java.sql.Timestamp.valueOf(month.plusMonths(1).atDay(1).atStartOfDay())
    def programs = ec.entity.find('zenith.erp.loyalty.LoyaltyProgram').condition('organizationPartyId',org).list()*.programId
    usage = [periodMonth:month.year * 100 + month.monthValue, activeUsers:activeUsers,
        totalProducts:ec.entity.find('mantle.product.Product').condition('ownerPartyId',org).condition('productTypeEnumId','PtAsset').count(),
        posTerminals:ec.entity.find('zenith.erp.pos.PosTerminal').condition('organizationPartyId',org).condition('isActive','Y').count(),
        totalTransactions:ec.entity.find('zenith.erp.pos.PosTransaction').condition('organizationPartyId',org)
            .condition('entryDate','>=',start).condition('entryDate','<',end).count(),
        totalStores:ec.entity.find('zenith.erp.stores.Store').condition('organizationPartyId',org).list().count {it.statusId != 'StClosed'},
        loyaltyMembers:programs ? ec.entity.find('zenith.erp.loyalty.LoyaltyMember').condition('programId','in',programs).condition('statusId','LmActive').count() : 0,
        activePromotions:ec.entity.find('zenith.erp.promotions.Promotion').condition('organizationPartyId',org).condition('isActive','Y').count()]
} finally { if (!disabled) ec.artifactExecution.enableAuthz() }
